const char *t_strcut(const char *src, const char *delim) {
    size_t len_src = strlen(src);
    size_t len_delim = strlen(delim);
    size_t pos = 0;

    for (size_t i = 0; i < len_src; ++i) {
        if (strncmp(src + i, delim, len_delim) == 0) {
            pos = i;
            break;
        }
    }

    if (pos == 0) {
        return src;
    }

    size_t len_sub = len_src - pos;
    char *sub = malloc(len_sub + 1);
    if (!sub) {
