bool ParseProtoUnlimited(const string& value, T* proto) {
  // Allocate enough memory for the proto message
  char* buffer = new char[sizeof(T)];
  if (buffer == nullptr) {
    return false;
  }

  // Read the first few bytes of the input string into the buffer
