	const struct http_hdrflg *f;

	if (fm->hdf[u] & HDF_FILTER)
		return (1);

	// Find the start of the header name
	e = fm->hd[u].b;
	while (*e != ':' && *e != '\0') {
		e++;
	}

	if (*e == '\0') {
